<?php
session_start();require_once __DIR__.'/includes/config.php';
if(empty($_SESSION['alogin'])||empty($_SESSION['uid'])){header('Location: index.php');exit;}
function h($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
$desde=trim((string)($_GET['desde']??''));$hasta=trim((string)($_GET['hasta']??''));$sede=(int)($_GET['sede_id']??0);$buscar=trim((string)($_GET['buscar']??''));
$sql="SELECT m.id,m.fecha_movimiento,m.motivo,m.autorizado_por,m.observaciones,a.id AS activo_id,a.codigo_inventario,a.descripcion,a.marca,a.modelo,uo.nombre AS origen,so.nombre AS sede_origen,ud.nombre AS destino,sd.nombre AS sede_destino,us.nombre_completo AS registrado_por FROM movimientos_activos m INNER JOIN activos a ON a.id=m.activo_id LEFT JOIN ubicaciones uo ON uo.id=m.ubicacion_origen_id LEFT JOIN sedes so ON so.id=uo.sede_id INNER JOIN ubicaciones ud ON ud.id=m.ubicacion_destino_id INNER JOIN sedes sd ON sd.id=ud.sede_id LEFT JOIN usuarios_sistema us ON us.id=m.registrado_por WHERE 1=1";
$params=array();
if($desde!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$desde)){$sql.=" AND DATE(m.fecha_movimiento)>=:desde";$params[':desde']=$desde;}
if($hasta!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$hasta)){$sql.=" AND DATE(m.fecha_movimiento)<=:hasta";$params[':hasta']=$hasta;}
if($sede>0){$sql.=" AND (uo.sede_id=:sede_origen OR ud.sede_id=:sede_destino)";$params[':sede_origen']=$sede;$params[':sede_destino']=$sede;}
if($buscar!==''){$sql.=" AND (a.codigo_inventario LIKE :codigo OR a.codigo_placa LIKE :placa OR a.descripcion LIKE :descripcion OR a.marca LIKE :marca OR a.modelo LIKE :modelo OR a.numero_serial LIKE :serial)";$like='%'.$buscar.'%';foreach(array(':codigo',':placa',':descripcion',':marca',':modelo',':serial') as $p)$params[$p]=$like;}
$sql.=" ORDER BY m.fecha_movimiento DESC,m.id DESC LIMIT 500";
$q=$dbh->prepare($sql);$q->execute($params);$movimientos=$q->fetchAll(PDO::FETCH_ASSOC);
$sedes=$dbh->query("SELECT id,nombre FROM sedes WHERE estado='ACTIVA' ORDER BY nombre")->fetchAll(PDO::FETCH_ASSOC);
include __DIR__.'/includes/topbar.php';
?>
<div class="content-wrapper"><div class="content-container"><?php include __DIR__.'/includes/leftbar.php'; ?><div class="main-page"><div class="container-fluid"><div class="row page-title-div"><div class="col-md-12"><h2 class="title">Historial de traslados</h2><p>Consulta los movimientos físicos registrados para los activos.</p></div></div><div class="row breadcrumb-div"><div class="col-md-12"><ul class="breadcrumb"><li><a href="dashboard.php">Inicio</a></li><li>Gestión de traslados</li><li class="active">Historial</li></ul></div></div></div>
<section class="section"><div class="container-fluid"><div class="panel"><div class="panel-heading"><div class="panel-title"><h5>Filtros de consulta</h5></div></div><div class="panel-body"><form method="get" class="row">
<div class="form-group col-md-3"><label>Buscar activo</label><input type="text" name="buscar" class="form-control" value="<?php echo h($buscar); ?>" placeholder="Código, placa, descripción, serial"></div>
<div class="form-group col-md-2"><label>Sede involucrada</label><select name="sede_id" class="form-control"><option value="0">Todas las sedes</option><?php foreach($sedes as $s): ?><option value="<?php echo (int)$s['id']; ?>" <?php echo $sede===(int)$s['id']?'selected':''; ?>><?php echo h($s['nombre']); ?></option><?php endforeach; ?></select></div>
<div class="form-group col-md-2"><label>Desde</label><input type="date" name="desde" class="form-control" value="<?php echo h($desde); ?>"></div><div class="form-group col-md-2"><label>Hasta</label><input type="date" name="hasta" class="form-control" value="<?php echo h($hasta); ?>"></div>
<div class="form-group col-md-3" style="padding-top:24px"><div style="display:flex; flex-wrap:wrap; align-items:center; gap:8px;"><button class="btn btn-primary" type="submit"><i class="fa fa-search"></i> Filtrar</button><a href="manage-traslados.php" class="btn btn-default">Limpiar</a><a href="registrar-traslado.php" class="btn btn-success">Nuevo traslado</a></div></div></form></div></div>
<div class="panel"><div class="panel-heading"><div class="panel-title"><h5>Movimientos registrados (máximo 500 resultados)</h5></div></div><div class="panel-body"><div class="table-responsive"><table class="table table-striped table-bordered"><thead><tr><th>Fecha y hora</th><th>Código</th><th>Activo</th><th>Origen</th><th>Destino</th><th>Motivo</th><th>Autorizado por</th><th>Registrado por</th></tr></thead><tbody>
<?php if(!$movimientos): ?><tr><td colspan="8" class="text-center">No se encontraron traslados con los filtros indicados.</td></tr><?php else: foreach($movimientos as $m): ?><tr><td><?php echo h($m['fecha_movimiento']); ?></td><td><a href="detalle-activo.php?id=<?php echo (int)$m['activo_id']; ?>"><strong><?php echo h($m['codigo_inventario']); ?></strong></a></td><td><?php echo h(trim(($m['descripcion']??'').' '.($m['marca']??'').' '.($m['modelo']??''))); ?></td><td><?php echo h(($m['sede_origen']??'').' — '.($m['origen']??'Sin ubicación')); ?></td><td><?php echo h(($m['sede_destino']??'').' — '.($m['destino']??'')); ?></td><td><?php echo h($m['motivo']); ?><?php if($m['observaciones']): ?><br><small><?php echo h($m['observaciones']); ?></small><?php endif; ?></td><td><?php echo h($m['autorizado_por']); ?></td><td><?php echo h($m['registrado_por']?:'—'); ?></td></tr><?php endforeach; endif; ?>
</tbody></table></div></div></div></div></section></div></div></div>
